  "headline": "Sucralfate is not on FDA's current shortage list as of 2026-10-21; the prior shortage posted 2023-01-04 is resolved",
  "headline_cites": ["D3"],
  "sentences": [
    {
      "text": "FDA's records show sucralfate is not on the current shortage list as of 2026-10-21, and the earlier shortage first posted on 2023-01-04 has been resolved.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East has 126 tablets of the 1 g presentation on hand, providing 16.6 days of supply at 7.6 tablets per day.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General has 193 tablets of the 1 g presentation on hand, providing 18.9 days of supply at 10.2 tablets per day.",
      "cites": ["D2"]
    },
    {
      "text": "The top-ranked purchasing option is to buy from Allergan, Inc., which is not on FDA's shortage list today and is supplied from the ABBVIE plant.",
      "cites": ["D4"]
    },
    {
      "text": "A secondary option is Amneal Pharmaceuticals NY LLC, also not on the shortage list, with its New York plant last inspected NAI on 2023-06-07.",
      "cites": ["D5"]
    },
    {
      "text": "A third option is Teva Pharmaceuticals USA, Inc., likewise not on the shortage list, supplied from the TEVA plant.",
      "cites": ["D6"]
    }
  ]
